import ctypes

def inverse_cdf_tdist(P, nu):
    # Load the GSL CBLAS library first
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    # Load the GSL library
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    # Define the function signature
    gsl.gsl_cdf_tdist_Pinv.argtypes = [ctypes.c_double, ctypes.c_int, ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_cdf_tdist_Pinv.restype = None

    # Handle edge cases
    if P == 0.0:
        return -float('inf')
    elif P == 1.0:
        return float('inf')
    elif nu == 1:
        # For nu = 1, the t-distribution is Cauchy
        return (1.0 / (P - 0.5)) if P > 0.5 else (-1.0 / (0.5 - P))
    elif nu == 2:
        # For nu = 2, use analytical solution
        return (1.0 / (P - 0.5)) if P > 0.5 else (-1.0 / (0.5 - P))

    # Prepare output variable
    t = ctypes.c_double()

    # Call the GSL function
    gsl.gsl_cdf_tdist_Pinv(P, int(nu), ctypes.byref(t))

    return t.value

