import ctypes
import numpy as np

class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix

    def __del__(self):
        if hasattr(self, 'matrix'):
            gsl.gsl_matrix_free(self.matrix)

def load_gsl_libraries():
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        return gsl
    except Exception as e:
        raise RuntimeError(f"Failed to load GSL libraries: {e}")

def numpy_to_gsl_matrix(np_array):
    if not isinstance(np_array, np.ndarray) or len(np_array.shape) != 2:
        raise ValueError("Input must be a 2D NumPy array")
    rows, cols = np_array.shape
    matrix = gsl.gsl_matrix_alloc(rows, cols)
    if not matrix:
        raise RuntimeError("Failed to allocate GSL matrix")
    data = (ctypes.c_double * (rows * cols))(*np_array.flatten().tolist())
    ctypes.memmove(ctypes.addressof(matrix.contents.data), data, ctypes.sizeof(data))
    return matrix

def gsl_matrix_to_numpy(gsl_matrix):
    rows = gsl_matrix.contents.size1
    cols = gsl_matrix.contents.size2
    data = (ctypes.c_double * (rows * cols))()
    ctypes.memmove(data, gsl_matrix.contents.data, ctypes.sizeof(data))
    return np.array(data, dtype=np.float64).reshape((rows, cols))

def compute_covariance(jacobian, epsrel, n):
    if not isinstance(jacobian, np.ndarray) or len(jacobian.shape) != 2:
        raise ValueError("Jacobian must be a 2D NumPy array")
    if jacobian.shape[0] < n or jacobian.shape[1] < n:
        raise ValueError("Jacobian dimensions must be at least n x n")
    if not isinstance(epsrel, float) or epsrel <= 0:
        raise ValueError("epsrel must be a positive float")

    gsl = load_gsl_libraries()

    # Define function prototypes
    gsl.gsl_multifit_covar.argtypes = [ctypes.POINTER(GSLMatrix), ctypes.c_double]
    gsl.gsl_multifit_covar.restype = None

    # Convert Jacobian to GSL matrix
    jacobian_gsl = numpy_to_gsl_matrix(jacobian)

    # Create covariance matrix
    covar = gsl.gsl_matrix_alloc(n, n)
    if not covar:
        raise RuntimeError("Failed to allocate covariance matrix")

    # Call GSL function
    gsl.gsl_multifit_covar(jacobian_gsl, epsrel)

    # Convert result to NumPy array
    covar_np = gsl_matrix_to_numpy(covar)

    # Clean up
    gsl.gsl_matrix_free(jacobian_gsl)
    gsl.gsl_matrix_free(covar)

    return covar_np

